function parkDifferentialLabelQuietly(storyKey) {
    try {
        getTracker().addLabel(storyKey, tcMaintenanceLedger.PARK_LABEL);
        console.log('✅ Parked differential request — labeled', storyKey, 'with', tcMaintenanceLedger.PARK_LABEL);
